\u0053\u007e\u0070\u007a\u0045\u0029\u0035\u007a\u0058\u0042\u006e\u003d\u0062\u0065\u0065\u0040\u0053\u006b\u003a\u0055\u0054\u0048\u003d\u004e\u0029\u0072\u002c\u0062\u0064\u0068\u002a\u006f\u0021\u007c\u0079\u0031\u005e\u0074\u004d\u0042\u007c\u0045\u0029\u0058\u0070\u003e\u002c\u0075\u0051\u0024\u007c\u0025\u0059\u0040\u0040\u0025\u0031\u0068\u0043\u0024\u0052\u003a\u0030\u0050\u0030\u0060\u0040\u0056\u004c\u0029\u0036\u006a\u002f\u0035\u007c\u0067\u0033\u006a\u0057\u003c\u0035\u0078\u0055\u0030\u0053\u0036\u0076\u0059\u004c\u0059\u0068\u005b\u002a\u0026\u0067\u005d\u005e\u004e\u006a\u0065\u0057\u004f\u0053\u0053\u0066\u003e\u0047\u0061\u0024\u0070\u0073\u0047\u0062\u0030\u0053\u0036\u0076\u0059\u004c\u0059\u0068\u005e\u006a\u006b\u005a\u0048\u0047\u0059\u003e\u0058\u005f\u0075\u0064\u0041\u006d\u0068\u0058\u006a\u0041\u0062\u0039\u006d\u006a\u007d\u003d\u0059\u0059\u003c\u002c\u006a\u0056\u0029\u0049\u0078\u0030\u0047\u004d\u0056\u0034\u0050\u006a\u004f\u004a\u003a\u005a\u003a\u003f\u0078\u002f\u0026\u0077\u0022\u0061\u003b\u0031\u005d\u0048\u0037\u004a\u003e\u005a\u0061\u0035\u0060\u006a\u003f\u002a\u0040\u0075\u0043\u0057\u0021\u0075\u0037\u0036\u0068\u006d\u006a\u007d\u003d\u0059\u0059\u0054\u004c\u0072\u005d\u003d\u0036\u0040\u0057\u005e\u0063\u0036\u006c\u0047\u0061\u0049\u006b\u003d\u006f\u002c\u0031\u0057\u0049\u0051\u0068\u0068\u003b\u0043\u006e\u0065\u007a\u0061\u0076\u006f\u0062\u0031\u0079\u0023\u0024\u0075\u0052\u006b\u007c\u0032\u0064\u003c\u0077\u0076\u0031\u0053\u0058\u0059\u006a\u004a\u005f\u0062\u0074\u004e\u0075\u0033\u0075\u0049\u0031\u007a\u005b\u0026\u0063\u0036\u0024\u003d\u0074\u004e\u003e\u0065\u0065\u0059\u0021\u004a\u0054\u004c\u005a\u004b\u0036\u0044\u006c\u0075\u0034\u0069\u003e\u0077\u0070\u0026\u0023\u002c\u0049\u007e\u007b\u0072\u0072\u002c\u0038\u0049\u003c\u0030\u006e\u002e\u0054\u0076\u006d\u0070\u0029\u0044\u004b\u0038\u0032\u002c\u0079\u0059\u0063\u002c\u004d\u004c\u0022\u007b\u0050\u0055\u0037\u003c\u0033\u0038\u0047\u0043\u0063\u0023\u0053\u0046\u0067\u005d\u0032\u0033\u0041\u0035\u0060\u0029\u004f\u0037\u0069\u0078\u0026\u0077\u0069\u005b\u0050\u0058\u0021\u0051\u0067\u0029\u003f\u005e\u006a\u0030\u0079\u0031\u004d\u007e\u0021\u0034\u006f\u0022\u0067\u0037\u0035\u0044\u005a\u005b\u0040\u0050\u0054\u003e\u006d\u0030\u0049\u0074\u0044\u005b\u0021\u0024\u0079\u0025\u0029\u0043\u0061\u002f\u0035\u005e\u003b\u0077\u002c\u0031\u0031\u0036\u0065\u007e\u0022\u004b\u003c\u0068\u003c\u002f\u0050\u0071\u0024\u0071\u0044\u0057\u0036\u002f\u0023\u0072\u003b\u0033\u003b\u0067\u0075\u006b\u002f\u005b\u0036\u0065\u0078\u0023\u0039\u005e\u003e\u003f\u006e\u0069\u007e\u0033\u004f\u002e\u0043\u0054\u006f\u0078\u0045\u004e\u0031\u002f\u007c\u002f\u007a\u005b\u0062\u0075\u0038\u0066\u005a\u0044\u0062\u0035\u0024\u0068\u0044\u007d\u0026\u0039\u007a\u0050\u0041\u0075\u0062\u0032\u0037\u005d\u0021\u006d\u0040\u0044\u0036\u0079\u0058\u003e\u0045\u004b\u0056\u006d\u0033\u0073\u003d\u003f\u0039\u0065\u0052\u002a\u002c\u005e\u0039\u0032\u0036\u0026\u0079\u005d\u003c\u005e\u0032\u0058\u0071\u0060\u0075\u0074\u002b\u0050\u0031\u0038\u003d\u0076\u0031\u0064\u0046\u0038\u0056\u005a\u0024\u0050\u0061\u004f\u0079\u0064\u0071\u004f\u003d\u003a\u0033\u002c\u0060\u0026\u0071\u0079\u007d\u007e\u002f\u0025\u007c\u0038\u0069\u005f\u0044\u0074\u0025\u0073\u004c\u002b\u0075\u006d\u0073\u0023\u0068\u0062\u004b\u0044\u0056\u0059\u0044\u003d\u0057\u006f\u006f\u006b\u0050\u007d\u004b\u0043\u0040\u0079\u0067\u003b\u0070\u0046\u003c\u0056\u0074\u0065\u0034\u002b\u0039\u0032\u0051\u0026\u0044\u002f\u004a\u0056\u007c\u0040\u003a\u0026\u006e\u002b\u006f\u005b\u0039\u0067\u007e\u0068\u0021\u0028\u0032\u003e\u005f\u0055\u0062\u005f\u0042\u0075\u0031\u007d\u0022\u003b\u006b\u006a\u002c\u006e\u003d\u004d\u0070\u006b\u0062\u004a\u0068\u003d\u0060\u0038\u0032\u0045\u0056\u0038\u0037\u0035\u0052\u0046\u003a\u006f\u0044\u007d\u002e\u002a\u0053\u0056\u0024\u0068\u0068\u0072\u004d\u002b\u0077\u004d\u006a\u0065\u0035\u0061\u002f\u0044\u005d\u005a\u0066\u006a\u006a\u005e\u0028\u0056\u003a\u0057\u0055\u0068\u0068\u0063\u004d\u004d\u0023\u0068\u005e\u0023\u0079\u0043\u006e\u0037\u0046\u0067\u0030\u0071\u0023\u0023\u003d\u0071\u0037\u0062\u002e\u002c\u0024\u007e\u0035\u0047\u002a\u0052\u0043\u003f\u002b\u0065\u0030\u003f\u004e\u0033\u002a\u0030\u007c\u0054\u002c\u0069\u0051\u0035\u0022\u0077\u0056\u0039\u0061\u0072\u0034\u005e\u005a\u0079\u003a\u006b\u003e\u004e\u005f\u0078\u004e\u006a\u002f\u0039\u0029\u0038\u006f\u007b\u0068\u0067\u0064\u0059\u0028\u0077\u0071\u0030\u0064\u002a\u004a\u0034\u0028\u0070\u002f\u0039\u0029\u0038\u006f\u007b\u0060\u0058\u0075\u0055\u007b\u006f\u0059\u0028\u0077\u0071\u0030\u0064\u005a\u0069\u0071\u003e\u0064\u0073\u0052\u007c\u0063\u0033\u003a\u0039\u002e\u006e\u002a\u0025\u0060\u0069\u0029\u0065\u0065\u0041\u0029\u0063\u0075\u0065\u0071\u0071\u0062\u006f\u004a\u0030\u0078\u006a\u005d\u007b\u0038\u006e\u0072\u0026\u007d\u0033\u0024\u003c\u0055\u004a\u0062\u0025\u0031\u006a\u006a\u006b\u002b\u003d\u0079\u0071\u0078\u007a\u0045\u0067\u003c\u0028\u003f\u0067\u0075\u002f\u0063\u003e\u0028\u006a\u006e\u002a\u0063\u0044\u0031\u003f\u0067\u006f\u0021\u0039\u0055\u006e\u0042\u002e\u0045\u0067\u0028\u004c\u003a\u0040\u005b\u003d\u0079\u0036\u0063\u003f\u003f\u0024\u003b\u007b\u002f\u0023\u0035\u0049\u0036\u007c\u0057\u0063\u004f\u0044\u0028\u005f\u0049\u0048\u007e\u004a\u0029\u0058\u0061\u0029\u003b\u0046\u0053\u0062\u0065\u0040\u006e\u007c\u0044\u0026\u0025\u007e\u0057\u006f\u003e\u0079\u0070\u0040\u0062\u0040\u0038\u002c\u004c\u0061\u0070\u006d\u0066\u0040\u0055\u006c\u006f\u0038\u007c\u0073\u002c\u0051\u004d\u0030\u0033\u0040\u0074\u0036\u0052\u0034\u0065\u0066\u0060\u0058\u0025\u0051\u0026\u0077\u003d\u004e\u0045\u003a\u0049\u0067\u0041\u0045\u0078\u0057\u007c\u007c\u0074\u0043\u0048\u003f\u0038\u004e\u006c\u0052\u006b\u0041\u0049\u0036\u0057\u005f\u0054\u0055\u002a\u0045\u0051\u0032\u004b\u0039\u004a\u006a\u0053\u0073\u0075\u004c\u0042\u005b\u004a\u0039\u0021\u002f\u0065\u0057\u002c\u0053\u006e\u0079\u004f\u0044\u0031\u0040\u002f\u0040\u005b\u0048\u0074\u003b\u006a\u002c\u0029\u0043\u005b\u0022\u0033\u0044\u002b\u0059\u002c\u0030\u006e\u005d\u0042\u003e\u0065\u0049\u003a\u0038\u0040\u003f\u0051\u0068\u002a\u006a\u0051\u0026\u0065\u006f\u002f\u0063\u0046\u0065\u004b\u0054\u0023\u0045\u0022\u004d\u007c\u006a\u0071\u0056\u003c\u004c\u005a\u006f\u0064\u0038\u006c\u007c\u0056\u004e\u0035\u0075\u0073\u007a\u0029\u004b\u0028\u004c\u005a\u0030\u004c\u006d\u0049\u002a\u0036\u006b\u0078\u005e\u0040\u003e\u003f\u004d\u002f\u0030\u004a\u006b\u003e\u0064\u0026\u007d\u002b\u0054\u0033\u0036\u004d\u0072\u003f\u0057\u0069\u0058\u0040\u0036\u0074\u0060\u004e\u0058\u0029\u0059\u006b\u0021\u0061\u0036\u0029\u003b\u0075\u007b\u0073\u005b\u0037\u006f\u004b\u003e\u0031\u006b\u0060\u002c\u0025\u0042\u0030\u002b\u0026\u0064\u0031\u0045\u0030\u007b\u0049\u0035\u0025\u0079\u003b\u0060\u006d\u0034\u0033\u0068\u0065\u0048\u0030\u002f\u004b\u007c\u006c\u0031\u0060\u002b\u0058\u0069\u007d\u006f\u004e\u0053\u004f\u007c\u003a\u0026\u0031\u0052\u0024\u0035\u005d\u0054\u0053\u006e\u0070\u006b\u006a\u0069\u0049\u005f\u0029\u0024\u005d\u0062\u0048\u007b\u007a\u003e\u0042\u003c\u007c\u0051\u0022\u005d\u007c\u0050\u0068\u003d\u0069\u007a\u0072\u0075\u006e\u004a\u0067\u005d\u0057\u004b\u002e\u0053\u002c\u0026\u003e\u004c\u002f\u0031\u002b\u0026\u0060\u0073\u0048\u002e\u0042\u0059\u005f\u003a\u0068\u003c\u007b\u0024\u0040\u006b\u0048\u005a\u0049\u006c\u0041\u0031\u006b\u0037\u0073\u0065\u0042\u0068\u007d\u005e\u007e\u0057\u0043\u0079\u0079\u006b\u0055\u0040\u003e\u0045\u004b\u0063\u0078\u006b\u0036\u0057\u0076\u0047\u0044\u0037\u003d\u0026\u0046\u005b\u003e\u003c\u003b\u005e\u0063\u007d\u0069\u003b\u0077\u007a\u0051\u005a\u0035\u0079\u0021\u004f\u007e\u0073\u003b\u003c\u0070\u0039\u003e\u0028\u0028\u0077\u0066\u0051\u0057\u0038\u0063\u004d\u0055\u0072\u0048\u0046\u005a\u005f\u003d\u0047\u006d\u0064\u0047\u0066\u002a\u004f\u0049\u0077\u0021\u002a\u004e\u0068\u0056\u003c\u007a\u0073\u0056\u0041\u0060\u004c\u0037\u0049\u0053\u0051\u0037\u0052\u0079\u0056\u0070\u0037\u0065\u0048\u0041\u0070\u0034\u004c\u003b\u006e\u003a\u006b\u0051\u007b\u0036\u0042\u004d\u0075\u0044\u0075\u006d\u0073\u0023\u0068\u0062\u0067\u0040\u0046\u003a\u002c\u0054\u006f\u0079\u0061\u0071\u0029\u005b\u007c\u0064\u002b\u0025\u006d\u006a\u0075\u0029\u002a\u002f\u007c\u004c\u0042\u0033\u004f\u0033\u0041\u002e\u0041\u003c\u002c\u007d\u0034\u004b\u0030\u003b\u0071\u005e\u0046\u002c\u0053\u006f\u0067\u0025\u0051\u004c\u0052\u003e\u004d\u007c\u0040\u0044\u0074\u0076\u006a\u0065\u005b\u0070\u0071\u0072\u0033\u0067\u0073\u005e\u0041\u0024\u0076\u0048\u007b\u0033\u003a\u0021\u0073\u006f\u0072\u004b\u002f\u0059\u0063\u0079\u004d\u0037\u0048\u005d\u007b\u0023\u0060\u0075\u0040\u0060\u0078\u0048\u0039\u0041\u0033\u0022\u0032\u002c\u0029\u0057\u0072\u0057\u0025\u0026\u003a\u0077\u0033\u0046\u003c\u0065\u006e\u0073\u0058\u0077\u002e\u0033\u0067\u004b\u0070\u0050\u0040\u0038\u007a\u0038\u006e\u003c\u0074\u0050\u0067\u0025\u005f\u0070\u0029\u0026\u003e\u003e\u0034\u0062\u004b\u004a\u0057\u003d\u0067\u0072\u0070\u003c\u0065\u0057\u0072\u0052\u0034\u0062\u007d\u0053\u0058\u0050\u0073\u0049\u0044\u003b\u005d\u004d\u0058\u0061\u0030\u0051\u0069\u0047\u0028\u0060\u0048\u0065\u005f\u003b\u0064\u0034\u0076\u005b\u005d\u0050\u0069\u0071\u0034\u003f\u002c\u0029\u005d\u002a\u0053\u004a\u0026\u003a\u0077\u0033\u0046\u003c\u0065\u006e\u0073\u0058\u0077\u002e\u007c\u005d\u0077\u0071\u002e\u0067\u0063\u0066\u0045\u0072\u0056\u0034\u006d\u0054\u0032\u0056\u007b\u003d\u005a\u0032\u006e\u0056\u0051\u0060\u0077\u004a\u0057\u003d\u0067\u0072\u0070\u003c\u0065\u0057\u0072\u0052\u0034\u0034\u003e\u0052\u006c\u002f\u0036\u0070\u002e\u0067\u0053\u003a\u006c\u006e\u0046\u002a\u0034\u002a\u0065\u0042\u006b\u0049\u0030\u0059\u003d\u0061\u0051\u0060\u0053\u0065\u006c\u003e\u0048\u0034\u0079\u0076\u002c\u0029\u005d\u002a\u0053\u004a\u0064\u0076\u005d\u003c\u0046\u002b\u0024\u0069\u003c\u0073\u0028\u002a\u002c\u0066\u0043\u0065\u006d\u0066\u0054\u006a\u003e\u0036\u0058\u004b\u0046\u0067\u0054\u0067\u0024\u0040\u005d\u005d\u007b\u003a\u0047\u0030\u0061\u005f\u0065\u004f\u0023\u0047\u0047\u0045\u0048\u006b\u005b\u0059\u003c\u0032\u007b\u003e\u004d\u0060\u007d\u0069\u0039\u0037\u0075\u0021\u0076\u0048\u0050\u003f\u0054\u0070\u0075\u0060\u0044\u004b\u007e\u0067\u007a\u0035\u007c\u0042\u0048\u005e\u004e\u0041\u0039\u0054\u007b\u0049\u0057\u002a\u004b\u0061\u003c\u002f\u002b\u007d\u007d\u007a\u0073\u0070\u0067\u0048\u0031\u002b\u0064\u0054\u006f\u004f\u0071\u0076\u007a\u0068\u0037\u0034\u0073\u0070\u0056\u007a\u0079\u0030\u0045\u0064\u0068\u002f\u002b\u0059\u004d\u002f\u0036\u0047\u002e\u0053\u0038\u0078\u0025\u006b\u004d\u007c\u0068\u002f\u002b\u0059\u0062\u0064\u0036\u0047\u0063\u0050\u0068\u006f\u003f\u0068\u007b\u007b\u0063\u006c\u0022\u007a\u003b\u0053\u0078\u0060\u0053\u004a\u0041\u003a\u0044\u0021\u004f\u006e\u0074\u0054\u006c\u006b\u004d\u007c\u0042\u0022\u0038\u003d\u003a\u006a\u0052\u0024\u0065\u006e\u0078\u003a\u003b\u0037\u006d\u007c\u0038\u006c\u0050\u0034\u005a\u0079\u006b\u0025\u0073\u0070\u003c\u0048\u0031\u002b\u007c\u0054\u0075\u0069\u0071\u0076\u0057\u006f\u0052\u0047\u004d\u0066\u0062\u0075\u003e\u005f\u0059\u0033\u004e\u0051\u0046\u0067\u006a\u0067\u0039\u006b\u005d\u005d\u0023\u0039\u007d\u0037\u006d\u007c\u0038\u006c\u0050\u0034\u005a\u0079\u006b\u0025\u0073\u0070\u003c\u0048\u004c\u002b\u007a\u0041\u0057\u005f\u0046\u0067\u0021\u0067\u0024\u0040\u005d\u005d\u007b\u003a\u007d\u0037\u0072\u0034\u0037\u006e\u0050\u0047\u0069\u0055\u005a\u002e\u0074\u0075\u006c\u005f\u0059\u0033\u0048\u0051\u0046\u0067\u0054\u0067\u0024\u0040\u005d\u005d\u007b\u003a\u0032\u0064\u0059\u0033\u0061\u0030\u0045\u0045\u002a\u006a\u0055\u0048\u004e\u007c\u0063\u002f\u004d\u006d\u0028\u006a\u0056\u0031\u005b\u0065\u0071\u0034\u0042\u0054\u0066\u007c\u0030\u0031\u0071\u005a\u0033\u0075\u0048\u0037\u006c\u003d\u0034\u0056\u002e\u003a\u007d\u005a\u0035\u0071\u0026\u0058\u0071\u0068\u0040\u005e\u0040\u0054\u0042\u003e\u0075\u002a\u007a\u0072\u0070\u0053\u003d\u0026\u0047\u0069\u0024\u007e\u0024\u0041\u002f\u003e\u0031\u0070\u006b\u005d\u0066\u0066\u004a\u0059\u0058\u0078\u0067\u0075\u0048\u0037\u006c\u003d\u0034\u003b\u0053\u0044\u0054\u003a\u004d\u0051\u0051\u0076\u0021\u005b\u0065\u0071\u0034\u0042\u0054\u003e\u003e\u0075\u0048\u0037\u006c\u003d\u0034\u0056\u002e\u002b\u0057\u0049\u007c\u006a\u006d\u007c\u004c\u0047\u005d\u0040\u007b\u007b\u004d\u005a\u0048\u0034\u004a\u003a\u0039\u0055\u002c\u006b\u0051\u0021\u0077\u0068\u0038\u0026\u0041\u0030\u003b\u004c\u007d\u0074\u0025\u0031\u002b\u004a\u0054\u006f\u004f\u0071\u0076\u0058\u0064\u0052\u0047\u003d\u0053\u005a\u0079\u0049\u0025\u0073\u0070\u0067\u0048\u0031\u002b\u0064\u0054\u006f\u004f\u0071\u0076\u0058\u0064\u0052\u0047\u003d\u0053\u005a\u0079\u0049\u0025\u0073\u0070\u0067\u0048\u0031\u002b\u0064\u0054\u006f\u004f\u0071\u0076\u0058\u0064\u0052\u0047\u003d\u0053\u005a\u0079\u0049\u0025\u0073\u0070\u0067\u0048\u0031\u002b\u0064\u0054\u006f\u004f\u0071\u0076\u0058\u0064\u0052\u0047\u003d\u0053\u005a\u0079\u0049\u0025\u0030\u0067\u0070\u0029\u003c\u003e\u0028\u0034\u0068\u0070\u006a\u0037\u004d\u0066\u0068\u0024\u005a\u007b\u0034\u0024\u007a\u0042\u003c\u0034\u0034\u007d\u006d\u003b\u007a\u0034\u007e\u002c\u0044\u0025\u0044\u0054\u0061\u003b\u0044\u0051\u003f\u0034\u0021\u007b\u004e\u005e\u006f\u0043\u0051\u0079\u002f\u0055\u005d\u0054\u0067\u005a\u0077\u0035\u0061\u0067\u002f\u0038\u0045\u003e\u0040\u0045\u0077\u0061\u0066\u006d\u0067\u005a\u0067\u003b\u0062\u0030\u0048\u0040\u003e\u005e\u0053\u0060\u0078\u0048\u0063\u0049\u0073\u0072\u002f\u002a\u005f\u0051\u0073\u005a\u004f\u006e\u0078\u0042\u0064\u0075\u0034\u006e\u006e\u0078\u005a\u0041\u0063\u0067\u0071\u0066\u006f\u0069\u0075\u0079\u004d\u0078\u0057\u0066\u0059\u005f\u003e\u006b\u002a\u0064\u0075\u0034\u006e\u006e\u0078\u0038\u0041\u007e\u005d\u0075\u0039\u004e\u0025\u0074\u0057\u002b\u0075\u005a\u006a\u0038\u005f\u006b\u004a\u0028\u0029\u007e\u0077\u0072\u002c\u0033\u0062\u0052\u0045\u006a\u0060\u0041\u005d\u0057\u0056\u0058\u0048\u0075\u006f\u0060\u006c\u007a\u006d\u0040\u0054\u002b\u006e\u0056\u0053\u0069\u0049\u0065\u002a\u0032\u0073\u0054\u0031\u003e\u0071\u0040\u0056\u004a\u002a\u0078\u0043\u0072\u003c\u004d\u0031\u0044\u0022\u0074\u004a\u0043\u006f\u0053\u0057\u0037\u0037\u006f\u006a\u0070\u0075\u0070\u0042\u002c\u0074\u005e\u005e\u0041\u007d\u0049\u0073\u007e\u003b\u0044\u006b\u004d\u0037\u0041\u004f\u0056\u0052\u006a\u0069\u003c\u0047\u005e\u0039\u0021\u0053\u0039\u0052\u0032\u0028\u006c\u006a\u0040\u0056\u004a\u0037\u006f\u002a\u0031\u002f\u006a\u0069\u0033\u0077\u0074\u004e\u0035\u0037\u005a\u004e\u0050\u0056\u0046\u007c\u006b\u0077\u0037\u0023\u0025\u006a\u0052\u0039\u0028\u0048\u0053\u0023\u0025\u0066\u007d\u0042\u0061\u0031\u007e\u0073\u003b\u0034\u003b\u0051\u0065\u005f\u0063\u0064\u0035\u0028\u004d\u002c\u0078\u0051\u006d\u0058\u0064\u003a\u0077\u0048\u0051\u0054\u0049\u006a\u0070\u002f\u004b\u002c\u004a\u0063\u0075\u0066\u0060\u004c\u003d\u0051\u0039\u004b\u007c\u0050\u0079\u0033\u003d\u0023\u0055\u0055\u0066\u003f\u003a\u0043\u0025\u0044\u0043\u0024\u0069\u005a\u005e\u0071\u0039\u0061\u0078\u006b\u007a\u0046\u0077\u003e\u0065\u0049\u0069\u0021\u005d\u0071\u006a\u0069\u0023\u004e\u007a\u007a\u0063\u0060\u0043\u007b\u004b\u006b\u0025\u0035\u0042\u0046\u0029\u0043\u003f\u0038\u0024\u004c\u007b\u0049\u006c\u0059\u0058\u0040\u0038\u003f\u0077\u006b\u0029\u006c\u0025\u003d\u0030\u0032\u0071\u0036\u0026\u0066\u005f\u003c\u0075\u0026\u0022\u0044\u005b\u0035\u0072\u002c\u006c\u006c\u003e\u0073\u006a\u003d\u007e\u007b\u0053\u0052\u0043\u0035\u0079\u0022\u006f\u0024\u002e\u007b\u0039\u006f\u0044\u0033\u0029\u0075\u005f\u0058\u003a\u004a\u0031\u005d\u0064\u006b\u007a\u0077\u0052\u005a\u0041\u0051\u003f\u0036\u0068\u0054\u002e\u0043\u007c\u0044\u0070\u0036\u0033\u0039\u0066\u006f\u0074\u0037\u0035\u005d\u0039\u006a\u0061\u0024\u002f\u0028\u0077\u0075\u0045\u0051\u004d\u0024\u0025\u0071\u0074\u0051\u007a\u0073\u0071\u004a\u003f\u007c\u0071\u0037\u006a\u007b\u0051\u0075\u0024\u006c\u004b\u005e\u0044\u0064\u0072\u005a\u0044\u0078\u0028\u003f\u0052\u0030\u0078\u0021\u0061\u0044\u0044\u0070\u0051\u0074\u004e\u0076\u0057\u0026\u002c\u006c\u0061\u006d\u006a\u0073\u0057\u005f\u0047\u0029\u0057\u0066\u0076\u0040\u0054\u0046\u0053\u007b\u0071\u0068\u0052\u003a\u0057\u0039\u0058\u0069\u0065\u003a\u0021\u0051\u0045\u0075\u004b\u0064\u0079\u0032\u0071\u0035\u0040\u004a\u004d\u0058\u0048\u0077\u007e\u005f\u0025\u002a\u004f\u002f\u0045\u0023\u0063\u002e\u0077\u0040\u0058\u0075\u0063\u004b\u004e\u0071\u004c\u0051\u0071\u0042\u0041\u0068\u0065\u0035\u004d\u005b\u0069\u0070\u006f\u002e\u004b\u0058\u0026\u0021\u003f\u0030\u0028\u007a\u0079\u0054\u003f\u006b\u0045\u002a\u006a\u0042\u007c\u002e\u003c\u0070\u0070\u0072\u006b\u0040\u0079\u0077\u006a\u007e\u002c\u0051\u0029\u007e\u0075\u005a\u0073\u0078\u0073\u0035\u004e\u0054\u002c\u0066\u004e\u004b\u0043\u0031\u0047\u0023\u0054\u0049\u006c\u0024\u0079\u0055\u0075\u004b\u003d\u004d\u004c\u005b\u0072\u006d\u0024\u004c\u005e\u006c\u003a\u0035\u0031\u0047\u002c\u004b\u006a\u0067\u0067\u0058\u0067\u002f\u0063\u007b\u006f\u0043\u003e\u0052\u0031\u005e\u0069\u004f\u006c\u0053\u0036\u0062\u004e\u007e\u0074\u006c\u005d\u0051\u007e\u0046\u0062\u002c\u007a\u0069\u006e\u0050\u005b\u006c\u0073\u003c\u0051\u003a\u0048\u0047\u0078\u0062\u0053\u0070\u0078\u005e\u0044\u002f\u0025\u0071\u005e\u0050\u006b\u0069\u007d\u007c\u0072\u006d\u004e\u0072\u0052\u006c\u006d\u0052\u0056\u003c\u006d\u006e\u0044\u0031\u0078\u005e\u004f\u0064\u0042\u0050\u004b\u0075\u0047\u007d\u0060\u0031\u007e\u0047\u006b\u007a\u0060\u0038\u0065\u0037\u005a\u006d\u007d\u002a\u0055\u0066\u005f\u0052\u0047\u0026\u0037\u006a\u006d\u0055\u0050\u0054\u0058\u0040\u0034\u0036\u005d\u0038\u005f\u0052\u0065\u005f\u0042\u0076\u0061\u0076\u0045\u0058\u005d\u005b\u0031\u007e\u0075\u003c\u007e\u0041\u0064\u0044\u0078\u0067\u0055\u0042\u0026\u0058\u002b\u007a\u0031\u006b\u006a\u0077\u005b\u0034\u003c\u0054\u003a\u0050\u007e\u0066\u007d\u004f\u004b\u0075\u0050\u004b\u0038\u006f\u0061\u006d\u006a\u0022\u0065\u006f\u002f\u0048\u004c\u006e\u004a\u007c\u0044\u0079\u004d\u0026\u0049\u003e\u003d\u0065\u006e\u003a\u003e\u006a\u0055\u004e\u007a\u0035\u0078\u0044\u004d\u007a\u0055\u004e\u0033\u0061\u0024\u0078\u0036\u004d\u0045\u0053\u0049\u005b\u0072\u0072\u0073\u003e\u0059\u005d\u0066\u0026\u004d\u005d\u0039\u004e\u005e\u0061\u0073\u0075\u005d\u003b\u0029\u005d\u0048\u007a\u004e\u002b\u0073\u0064\u0029\u0025\u003b\u0078\u002c\u0043\u002b\u0069\u007a\u0039\u0061\u0075\u005f\u0043\u0040\u006c\u0041\u0033\u0056\u0056\u0042\u004b\u0060\u006a\u0062\u003d\u0043\u002b\u0024\u003c\u004c\u007e\u004b\u0055\u0075\u004a\u007d\u004b\u002f\u0077\u0057\u004b\u0030\u005a\u0039\u005b\u0059\u0023\u004c\u003b\u0021\u0059\u0065\u0061\u0057\u0028\u002b\u0044\u0068\u007a\u0029\u004b\u0028\u0063\u0068\u0074\u0045\u0034\u0073\u002a\u0037\u003c\u006d\u0026\u0049\u0059\u0059\u0051\u0023\u002e\u0067\u005d\u0068\u0024\u0070\u003c\u0048\u006c\u007d\u005e\u0061\u0029\u007d\u0022\u002c\u0026\u0036\u0063\u0025\u004a\u0025\u006e\u0026\u004e\u0048\u0030\u004f\u0056\u0066\u0072\u0054\u005a\u006a\u0077\u0049\u003a\u0031\u006d\u0056\u0057\u007e\u0056\u0043\u0033\u0048\u0057\u0022\u006a\u0072\u0023\u003d\u004c\u002f\u0078\u0033\u0029\u0023\u004d\u0078\u002c\u004f\u0071\u0079\u006d\u0062\u0023\u0039\u0026\u0044\u007b\u002c\u006c\u006b\u007d\u004b\u0032\u0079\u0051\u0069\u0065\u007e\u003a\u0038\u002e\u0053\u0060\u0057\u0042\u0077\u004d\u005a\u0058\u0039\u004e\u006e\u003d\u003b\u0042\u003d\u0060\u0078\u0077\u0025\u004f\u0036\u002a\u0068\u006d\u005d\u002c\u002f\u0043\u0025\u006c\u0045\u0032\u0078\u0021\u004c\u0028\u0067\u0071\u0057\u005e\u0051\u0037\u006d\u006c\u0030\u007d\u0035\u006d\u005b\u004b\u0039\u0040\u007a\u0024\u0033\u003d\u0064\u007c\u0029\u0067\u002f\u0074\u0023\u0041\u002f\u0076\u007c\u0024\u006c\u004d\u007c\u0038\u0043\u0025\u0058\u002e\u0025\u004f\u0066\u0022\u003d\u0044\u003e\u004c\u0024\u0038\u0032\u0057\u0063\u007c\u0055\u0079\u007a\u0068\u0028\u007b\u0058\u0070\u0028\u003b\u003e\u0048\u0064\u003d\u0057\u0021\u0068\u004d\u0032\u006c\u0050\u006f\u0066\u0049\u0073\u0029\u0073\u0043\u004f\u006c\u0037\u004f\u0047\u007a\u0057\u0026\u0075\u0035\u006f\u0066\u0071\u003a\u0077\u007c\u0046\u0079\u0025\u004d\u0055\u0041\u002c\u0051\u004d\u006f\u004f\u0041\u0041\u007e\u004d\u0028\u0045\u0060\u0062\u0033\u0052\u003f\u0069\u0047\u006d\u007b\u0021\u007e\u003a\u004d\u007c\u0056\u0079\u0066\u005f\u0056\u005b\u0048\u0050\u0078\u007d\u0074\u0045\u0046\u0022\u006b\u0031\u0071\u005a\u005e\u0025\u0049\u0048\u0063\u0065\u0058\u0076\u0033\u006d\u0058\u0051\u0029\u003b\u0074\u005d\u006c\u0045\u003e\u0044\u004e\u0049\u0035\u0050\u006d\u006a\u004f\u0057\u0021\u0063\u0037\u002e\u0056\u0055\u0021\u007e\u002b\u0032\u0062\u0021\u0040\u0028\u007a\u0029\u003c\u006e\u0060\u0038\u0044\u002e\u0063\u0033\u0038\u0073\u0038\u0055\u006d\u0032\u0064\u0044\u0070\u0068\u0075\u0029\u0078\u0077\u0070\u0057\u0066\u0045\u0055\u006e\u004c\u002a\u0069\u0060\u0046\u004b\u0076\u0065\u0049\u0023\u0073\u0051\u0073\u0067\u0025\u002f\u0077\u0048\u006a\u0061\u0056\u0071\u005a\u0021\u006e\u0060\u004a\u0022\u0042\u003d\u003f\u002f\u0070\u004c\u0023\u007d\u0028\u003b\u0022\u0024\u003c\u0049\u0053\u0025\u0059\u0029\u0063\u0043\u006b\u0024\u004b\u0058\u0063\u0033\u0038\u0073\u007b\u006d\u0065\u006e\u0078\u0056\u007d\u003d\u0074\u006c\u002e\u006e\u0025\u003b\u0066\u0059\u0051\u0049\u003e\u0028\u0070\u0047\u0076\u004c\u0064\u0044\u0034\u0043\u0022\u005a\u0067\u005b\u0053\u004a\u003f\u0035\u0060\u0065\u0076\u0034\u002b\u0053\u0035\u0039\u0038\u004e\u0062\u003b\u004a\u006a\u0042\u003c\u0035\u0028\u0022\u003f\u0073\u007a\u0075\u0056\u004a\u0045\u0077\u0026\u0052\u006c\u0066\u0039\u0058\u0041\u0073\u0037\u007b\u006a\u0063\u003a\u0021\u004c\u002b\u0056\u0037\u002c\u0064\u006e\u006d\u0072\u0059\u005a\u003f\u0065\u0058\u004c\u003c\u003c\u0056\u0031\u0043\u0045\u0068\u005d\u0060\u0048\u0054\u006b\u0051\u0053\u003c\u0048\u0045\u0038\u0036\u0023\u0032\u0031\u0062\u0029\u0035\u0074\u0021\u006e\u0041\u0050\u005a\u003b\u0023\u002e\u0021\u0036\u0079\u0046\u0046\u0025\u005a\u0034\u0077\u0062\u006e\u006e\u006b\u004a\u0041\u0041\u0056\u007e\u0039\u005b\u005e\u0029\u0035\u005b\u006d\u0066\u0044\u0058\u0048\u0023\u0069\u0076\u0042\u0061\u006f\u005d\u005d\u007d\u0026\u003f\u003a\u0051\u0039\u0052\u004d\u0030\u0036\u0047\u0023\u0022\u0063\u002a\u0078\u0071\u0053\u0061\u004b\u0075\u0063\u006c\u0038\u006c\u0061\u0036\u0049\u0047\u0064\u003e\u0028\u0058\u005e\u0028\u0045\u0061\u0077\u006e\u005e\u0046\u002e\u002f\u0043\u005d\u0065\u0023\u0071\u0032\u007d\u0047\u006a\u003e\u0052\u007a\u0045\u0039\u0048\u0056\u007c\u0047\u003f\u005b\u0046\u007d\u004d\u005d\u0071\u0022\u005d\u0038\u003e\u002a\u0077\u0026\u0062\u0045\u0037\u0032\u0044\u007b\u0026\u0070\u0052\u0076\u006a\u0024\u0035\u003c\u0021\u0077\u0056\u0039\u0037\u004f\u0030\u0044\u007c\u0047\u003f\u005b\u0046\u007d\u0049\u003c\u0035\u0044\u0063\u0047\u0053\u0052\u0065\u0066\u004c\u007b\u0023\u0023\u002c\u0021\u0063\u002f\u002f\u0028\u007c\u0069\u0060\u0044\u007d\u0054\u007b\u002e\u0035\u0054\u002c\u0021\u0040\u0032\u002a\u0063\u005a\u0022\u0061\u0062\u0053\u005d\u006a\u0060\u0039\u0060\u0078\u005a\u0022\u003a\u0071\u0067\u0058\u0043\u0031\u007a\u006b\u0035\u0046\u0076\u0064\u0037\u0047\u0049\u002f\u0055\u0074\u005f\u0059\u0038\u0069\u003b\u0066\u0061\u004d\u006b\u0047\u0057\u0048\u0051\u0044\u0069\u003b\u0061\u0042\u0065\u0076\u005f\u007d\u0077\u005d\u0051\u003e\u007a\u0069\u006f\u0022\u003f\u0046\u007a\u0063\u0069\u004e\u0038\u0052\u0058\u0045\u0044\u0064\u002e\u003e\u0030\u0030\u0069\u0057\u006d\u0053\u0053\u002a\u002e\u003b\u0051\u0056\u0032\u004c\u007e\u0077\u004a\u0066\u006d\u003f\u0046\u0079\u0031\u003d\u007a\u004f\u0050\u0030\u0069\u0044\u0023\u004c\u005f\u003f\u005a\u0039\u0065\u0050\u003f\u0034\u0070\u0033\u0048\u0047\u0055\u0033\u0077\u0028\u0030\u0031\u0059\u004a\u0062\u007a\u0075\u0059\u0047\u0049\u006d\u0041\u006b\u0051\u0053\u003c\u0048\u0045\u0044\u0058\u0047\u0031\u0053\u0063\u0060\u0078\u005a\u0022\u003a\u0071\u004c\u0065\u0055\u004d\u0034\u002f\u0055\u0074\u005f\u0059\u0038\u0064\u002a\u0070\u007b\u0048\u006b\u004e\u0074\u0075\u0046\u004f\u0074\u005f\u006a\u003e\u0064\u005f\u006c\u0052\u003a\u007d\u0037\u003a\u006b\u005b\u0041\u007e\u0031\u0039\u005e\u004a\u003f\u0045\u0059\u0046\u0028\u003a\u0079\u007c\u0069\u003b\u0037\u0035\u0051\u0043\u007d\u0033\u006a\u0069\u0076\u0046\u0059\u0023\u0067\u0069\u006e\u003e\u0066\u0049\u005d\u0055\u0024\u0063\u0034\u0045\u0054\u0059\u0052\u007a\u0052\u0069\u0077\u0046\u0041\u0072\u0060\u0030\u006d\u004c\u003e\u0053\u0063\u004f\u0042\u003e\u0059\u0062\u003d\u005e\u004e\u0057\u0030\u007a\u0055\u0048\u004c\u0043\u006c\u0058\u004a\u0026\u0039\u0024\u004c\u002f\u004d\u0074\u0073\u0076\u005f\u0058\u0046\u0056\u004b\u0052\u005f\u0058\u0029\u0045\u0029\u0065\u0053\u0053\u0047\u005b\u005a\u007b\u0029\u0058\u003c\u0034\u003d\u006c\u002c\u0060\u0061\u007d\u003f\u0065\u0065\u006c\u0054\u007d\u004d\u005b\u0021\u0056\u006d\u0078\u0060\u0030\u0048\u0032\u007d\u0021\u0076\u0032\u005b\u003d\u003a\u0042\u006f\u002e\u0061\u0061\u0022\u0024\u0045\u003f\u0065\u005a\u0075\u0054\u004c\u0079\u0045\u007d\u0048\u0074\u0068\u0034\u0060\u007c\u0022\u0055\u0070\u005a\u0021\u0060\u003b\u005e\u0064\u0021\u006d\u0043\u0062\u0039\u0029\u007b\u0078\u0040\u0045\u006e\u002c\u006b\u006f\u0026\u0066\u0034\u0077\u0048\u0047\u0065\u0044\u005b\u0059\u0040\u0031\u0044\u003c\u0054\u0057\u004a\u0064\u0021\u0048\u005d\u0079\u0055\u0040\u004e\u0063\u0070\u0023\u006f\u0026\u0065\u0060\u007d\u006a\u007b\u0030\u004c\u003a\u0042\u0072\u004e\u0029\u002e\u0033\u006b\u0025\u002a\u0025\u002e\u0040\u0059\u004e\u0025\u0033\u0049\u0032\u0033\u006b\u0025\u002a\u0025\u002e\u005a\u0039\u003c\u0068\u0039\u0046\u003a\u0063\u0036\u002c\u006e\u0069\u004c\u0034\u002e\u0059\u0021\u004f\u0066\u0024\u0065\u0062\u0063\u0045\u0029\u0055\u0047\u004d\u0033\u0045\u004d\u0033\u006b\u0025\u002a\u0050\u005a\u0057\u0059\u0050\u003a\u0040\u0055\u0054\u007d\u006d\u0036\u0022\u004f\u004a\u005e\u005d\u0060\u0059\u0035\u004c\u0058\u0045\u003e\u005f\u006e\u0038\u006c\u004b\u003c\u0068\u0062\u0043\u007d\u007c\u007b\u0051\u0029\u0037\u0062\u002a\u0067\u0041\u0067\u0023\u0026\u002a\u0056\u0073\u003c\u0048\u0072\u0052\u0076\u0028\u003b\u007e\u0031\u006e\u0039\u0037\u0076\u0058\u0058\u003c\u0061\u0064\u0062\u007a\u0059\u0023\u0066\u0076\u003f\u003c\u006e\u0038\u002e\u0059\u005b\u0035\u006a\u0058\u0023\u005e\u003c\u0051\u005b\u006f\u0059\u0021\u002c\u0049\u0039\u0076\u0062\u0024\u005e\u0024\u0064\u0063\u002e\u002e\u007c\u0046\u003a\u006d\u0045\u0071\u0047\u0025\u007e\u003a\u003a\u005b\u0043\u0038\u0077\u006c\u004b\u0050\u007c\u002c\u0031\u0032\u0053\u0021\u0068\u0034\u0074\u0066\u003b\u0043\u002a\u0057\u005e\u0058\u0074\u0032\u0070\u0076\u0028\u0024\u0072\u0044\u006b\u0035\u0042\u0021\u0056\u007e\u0078\u0074\u0022\u0073\u007a\u0041\u0048\u0074\u0052\u0071\u006c\u005a\u0043\u0042\u0062\u0024\u005e\u0024\u0069\u0063\u0059\u0023\u0048\u0074\u0078\u0071\u0051\u0041\u003a\u0023\u0055\u0050\u0031\u006b\u0078\u0076\u0076\u006c\u0075\u0030\u0055\u0021\u0032\u0024\u0078\u0064\u0055\u0050\u0031\u006b\u007d\u0023\u0056\u0049\u004c\u0029\u0071\u0075\u0076\u0044\u003f\u006b\u0070\u0023\u0035\u006f\u005a\u003e\u0067\u0050\u0069\u007c\u002e\u0064\u0047\u0026\u0028\u0040\u0071\u0075\u0043\u0044\u003f\u006b\u0071\u0075\u0049\u005a\u0050\u0071\u007b\u0050\u007c\u005b\u003a\u005f\u003a\u002e\u0042\u005a\u007a\u0023\u006f\u004f\u0074\u003b\u0062\u0021\u0055\u003e\u0030\u0043\u0060\u0069\u007c\u003f\u0023\u0070\u0026\u002c\u0032\u0059\u0057\u0029\u002b\u005d\u0022\u0078\u0058\u0026\u0065\u0064\u0054\u0075\u0052\u0044\u002f\u003d\u0073\u003d\u002e\u0055\u005f\u005f\u003a\u002e\u0042\u005a\u007a\u0023\u006f\u004f\u0074\u003b\u0062\u0021\u0055\u003e\u0055\u0031\u0022\u0031\u005f\u0037\u0045\u0048\u0070\u005a\u0057\u003e\u005d\u004b\u0051\u0060\u002f\u004e\u007a\u0071\u0067\u0074\u003b\u0022\u0051\u007a\u006c\u0060\u0078\u0053\u0046\u0076\u003c\u0056\u007e\u0074\u0035\u007d\u0032\u002a\u0074\u004c\u0059\u002b\u002a\u0066\u004c\u004b\u004c\u0050\u006e\u0034\u0077\u007e\u005f\u002b\u007c\u0043\u0055\u0043\u0057\u0074\u0029\u0031\u0042\u0036\u003e\u0062\u005a\u0022\u0049\u002c\u003c\u0052\u0054\u0040\u0078\u005d\u0052\u0025\u007b\u0045\u0021\u004f\u006e\u0026\u007c\u0032\u0024\u0054\u002f\u0031\u0050\u004c\u006b\u0040\u003b\u007e\u0023\u007b\u0074\u003b\u0063\u0029\u002b\u003e\u0051\u0057\u0050\u002e\u0069\u004c\u003d\u007d\u0061\u0035\u003d\u0079\u002b\u0029\u0054\u0061\u0072\u002b\u002b\u002e\u0054\u0039\u0068\u004d\u0057\u0038\u004f\u0079\u0046\u0073\u0029\u004d\u004b\u0079\u0070\u0061\u0057\u0057\u0061\u0069\u0079\u0033\u0028\u003f\u0030\u0063\u007d\u002c\u0062\u007a\u006d\u0054\u0041\u0075\u007e\u0029\u0051\u0033\u0026\u0040\u0030\u0063\u0070\u006d\u0056\u0079\u007c\u0032\u0042\u0045\u0072\u002e\u0056\u0034\u007d\u0039\u0036\u0073\u0022\u003f\u0055\u004b\u006f\u0029\u0038\u0045\u0022\u0078\u0059\u0072\u0041\u0056\u003c\u0026\u0047\u0040\u0078\u0066\u004c\u0069\u003a\u0038\u0023\u004f\u002c\u0038\u007b\u006c\u0073\u004c\u0059\u003f\u0031\u0068\u004f\u0065\u0064\u0049\u0023\u0063\u005d\u004a\u0037\u004d\u0074\u0069\u0054\u006e\u0078\u0070\u002e\u0055\u006c\u005d\u0040\u0070\u006d\u0049\u0079\u0038\u003c\u004b\u0039\u003d\u002b\u0071\u007d\u006e\u0064\u0056\u0054\u007c\u0038\u005d\u004c\u0039\u0072\u0058\u003c\u0067\u0024\u0049\u0042\u0050\u0046\u0065\u004c\u002e\u0066\u0037\u0026\u0057\u004d\u0030\u0034\u006b\u0042\u0051\u0056\u0040\u0033\u004b\u003b\u0026\u0051\u0025\u0047\u0051\u0068\u0023\u002c\u004c\u0055\u0051\u0036\u0046\u0064\u004a\u007d\u0061\u0022\u0076\u0044\u0021\u0040\u0023\u0056\u007c\u006e\u0021\u0051\u0040\u004e\u004c\u0033\u007e\u002b\u0025\u0064\u0051\u004d\u0036\u0039\u006e\u005d\u006f\u003c\u0046\u004a\u0055\u003d\u002e\u0061\u0025\u0048\u0064\u0033\u004b\u0063\u006e\u0034\u0038\u004a\u0037\u007a\u0026\u005d\u005d\u0067\u007c\u0040\u0054\u0041\u0033\u0055\u004c\u006f\u002c\u003c\u0026\u0075\u0073\u0026\u0037\u0046\u0050\u004b\u0065\u0078\u0050\u003c\u0023\u006f\u002c\u003c\u0026\u0075\u0073\u0031\u003e\u0030\u0047\u006e\u0029\u0029\u002c\u0022\u006d\u0058\u0038\u0034\u0078\u0037\u0042\u0071\u0072\u0050\u005e\u003a\u005e\u0049\u0062\u006d\u0072\u005a\u0053\u0024\u003e\u004f\u0069\u0061\u0063\u003c\u0070\u007c\u0071\u0046\u007c\u0065\u0050\u0064\u0053\u006e\u0035\u0079\u002f\u0042\u0067\u0038\u007d\u0067\u007e\u0057\u0065\u0048\u0052\u0074\u0040\u0063\u003a\u005e\u0049\u0062\u006d\u0072\u0049\u0070\u006d\u0067\u007a\u005d\u0047\u0034\u004f\u0070\u005a\u005a\u006c\u0067\u006d\u004a\u0049\u0051\u0066\u0046\u0078\u0072\u0022\u002e\u0032\u0056\u0022\u002b\u0057\u0024\u0058\u002e\u0064\u006e\u0072\u0045\u002c\u0058\u004d\u002b\u0029\u0039\u0033\u0023\u0079\u0069\u0040\u0023\u0036\u0066\u0050\u0046\u0065\u004c\u0043\u0038\u002b\u0077\u003d\u0050\u0053\u0053\u0028\u007c\u0045\u006f\u0035\u0045\u0021\u0069\u007a\u0047\u0030\u0067\u0053\u0031\u0037\u005b\u007c\u0064\u0046\u0045\u0069\u002e\u0032\u0038\u004f\u0060\u0032\u0051\u004f\u004a\u007a\u0047\u0076\u0047\u0072\u0046\u005b\u0079\u0025\u0053\u0035\u0045\u0069\u0028\u0051\u0022\u0037\u0049\u0072\u0069\u0042\u0074\u0060\u0073\u006d\u0037\u0022\u0022\u0054\u004e\u0072\u0069\u0042\u0074\u0060\u0073\u004e\u0056\u0046\u0029\u0051\u0079\u003f\u002b\u005b\u002c\u0057\u007a\u0049\u0075\u0031\u004a\u0021\u005d\u0078\u003e\u0065\u007c\u0042\u005a\u0039\u005e\u0068\u0053\u0053\u0023\u0042\u003b\u0044\u004e\u0031\u005f\u0026\u0042\u002f\u0037\u0061\u0066\u0076\u003f\u003c\u006e\u0038\u0035\u0052\u005e\u0069\u007b\u0076\u002e\u0041\u0049\u003e\u0070\u004b\u0037\u0026\u0077\u0047\u0043\u006f\u0042\u0073\u0056\u0057\u0066\u002c\u0033\u0067\u0072\u0040\u0021\u005e\u0025\u0061\u0054\u0076\u0047\u004b\u002e\u003a\u004f\u005a\u0033\u0024\u0041\u0040\u0021\u0021\u0038\u002b\u0052\u0037\u0051\u0022\u002f\u004f\u0034\u0075\u0059\u0040\u0038\u0025\u0036\u0052\u0052\u004e\u0025\u0034\u0031\u003a\u0048\u0035\u0079\u0045\u0078\u0040\u0069\u0036\u0033\u004b\u0041\u0071\u0063\u006f\u006d\u0048\u003e\u003c\u006b\u005e\u005f\u0066\u0058\u0042\u0067\u004c\u0077\u002c\u003c\u0062\u002f\u0065\u0055\u007e\u0021\u006e\u0051\u0057\u0051\u0025\u0036\u0076\u0051\u007b\u0054\u004f\u002e\u005b\u0078\u003e\u003c\u004b\u0037\u006d\u0077\u0023\u002b\u007d\u0064\u004f\u002b\u0051\u004b\u0042\u0062\u0026\u003d\u003c\u0076\u0075\u0077\u0033\u004c\u0054\u006a\u005f\u004e\u0075\u006b\u0057\u0078\u0023\u0054\u005d\u0054\u0026\u0047\u0029\u0059\u007c\u0044\u0066\u003f\u0036\u0040\u007d\u007c\u0049\u004c\u003a\u0050\u003c\u0073\u0077\u006b\u0037\u0042\u003e\u003d\u002a\u0041\u0051\u007b\u0036\u0039\u0067\u0061\u007e\u0046\u003c\u003d\u0036\u0079\u0072\u0038\u0032\u0038\u0065\u004f\u002b\u0051\u004b\u004a\u004b\u0063\u0073\u006f\u0036\u0071\u0077\u0041\u007b\u0044\u0076\u0074\u0048\u0025\u0074\u0029\u0053\u005b\u0057\u0046\u0033\u004a\u004a\u0033\u0023\u0024\u0076\u004e\u0035\u007d\u0074\u006d\u0043\u0077\u0041\u0050\u0062\u0046\u0032\u0069\u0040\u002b\u0058\u0079\u0037\u0071\u0042\u0023\u0031\u002f\u006c\u0048\u007b\u002c\u0051\u004c\u0046\u0028\u0058\u0045\u006d\u0068\u0038\u002e\u002e\u007e\u0068\u0053\u0034\u0056\u006b\u0078\u0052\u002a\u0037\u007a\u006e\u0038\u007b\u0051\u0058\u004b\u0043\u0069\u003e\u006b\u005e\u0074\u0021\u0067\u003b\u004d\u004c\u0079\u003a\u0031\u0059\u0075\u0074\u002c\u0071\u006c\u005a\u0060\u0042\u0062\u0024\u004a\u0024\u0068\u0038\u0036\u0024\u0022\u004d\u0063\u0077\u0056\u0040\u005b\u0073\u003d\u005b\u0061\u0059\u0075\u0062\u0067\u0022\u0035\u006b\u0024\u0051\u0052\u0037\u0061\u0026\u007c\u006c\u0079\u003b\u006d\u0068\u003a\u0062\u0077\u006b\u005b\u0051\u004f\u002c\u0079\u004c\u0049\u004d\u0056\u0059\u007b\u0031\u0030\u0073\u003b\u007e\u0042\u0023\u0061\u0057\u0072\u002a\u0043\u006c\u006f\u0059\u0038\u0068\u0054\u0036\u0060\u006e\u0035\u006d\u0076\u004a\u007b\u0066\u0071\u0047\u005a\u0029\u0053\u0068\u003f\u0060\u002f\u0033\u006b\u0025\u002a\u0050\u005a\u004c\u004c\u0041\u0031\u0065\u0043\u004d\u0076\u0076\u0021\u003f\u0036\u0031\u0039\u0037\u006b\u0026\u002a\u0054\u0042\u002b\u0074\u0076\u006a\u0065\u0066\u005f\u0032\u0047\u0048\u0021\u0030\u0050\u0073\u0036\u0060\u0047\u0035\u0040\u002b\u004f\u004e\u007b\u0037\u004e\u0052\u0036\u004d\u0045\u0053\u0049\u005b\u0074\u002c\u002b\u0077\u004f\u003d\u0063\u0056\u005e\u0061\u0044\u004f\u0053\u0053\u0066\u003e\u0045\u0039\u0059\u004e\u004e\u0075\u002a\u006c\u007e\u0056\u003e\u005f\u0076\u0023\u006f\u0026\u0065\u0060\u007d\u0031\u0040\u007e\u0047\u0070\u0032\u0037\u006d\u003e\u0072\u0076\u0043\u0053\u0060\u005f\u0074\u002c\u0026\u0062\u0053\u0063\u0056\u005e\u0061\u005e\u003c\u004f\u0035\u003d\u0025\u0070\u0043\u0076\u0028\u0051\u0060\u0029\u0053\u0031\u003c\u002c\u0079\u0068\u006d\u0042\u0037\u004b\u0071\u005e\u0051\u0057\u0035\u004e\u0062\u0052\u006e\u0052\u0037\u0073\u003c\u003c\u0036\u0068\u0048\u0033\u006f\u0079\u002f\u005e\u0024\u0048\u0048\u005f\u0039\u007d\u0047\u006a\u0074\u0044\u0036\u0051\u003e\u0069\u0064\u0075\u0025\u0031\u0030\u003f\u003b\u0039\u0061\u002a\u006e\u0023\u0030\u0069\u0050\u004e\u0055\u0052\u0077\u005d\u0056\u0054\u003a\u0075\u004d\u0024\u0070\u0030\u0067\u0032\u002e\u0066\u004a\u0030\u004c\u0079\u006a\u004f\u0039\u003a\u0062\u0052\u006e\u0052\u0029\u0073\u002c\u0076\u004a\u0030\u0070\u0079\u0078\u0066\u0048\u0076\u004b\u0044\u003e\u0056\u0070\u004e\u004e\u006a\u006b\u007a\u004b\u0075\u0069\u0052\u0070\u0037\u004b\u0044\u003e\u0056\u005b\u0076\u004e\u006a\u0029\u006f\u004b\u0075\u007d\u0064\u005e\u0074\u0041\u0031\u0057\u005d\u005f\u002c\u0042\u0042\u007a\u0056\u004e\u0071\u0078\u0046\u006e\u0025\u004b\u0044\u0036\u0023\u0043\u0041\u0025\u0054\u0074\u0064\u0030\u0024\u0026\u002e\u007e\u006c\u0021\u0026\u0051\u006e\u0030\u0075\u0058\u003b\u0059\u0053\u0043\u0048\u003e\u002c\u006b\u0030\u0051\u0079\u006a\u004f\u0022\u003a\u0062\u0052\u007c\u0052\u0025\u007d\u003c\u003c\u0024\u0025\u0064\u0031\u004d\u0056\u0070\u004c\u0061\u0040\u002e\u0060\u007d\u006c\u0078\u0023